insert into businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('JVS Plumbing','Home Services','Lathrop','17036 S Harlan Road, Lathrop, CA 95330','(209) 229-5487','https://www.jvsplumb.com/','Residential and commercial plumbing provider explicitly advertising service in Lathrop, including drains, leak detection and water heaters. Confirm service fit, quote, emergency response and holiday availability directly. Other focus-city coverage and license/insurance claims have not been independently verified.','approved',true,false,null,0,'editorial_first_party','https://www.jvsplumb.com/contact-us','first_party_website_desk_check',now()) returning id into bid;
